/* eslint-disable no-restricted-syntax, no-invalid-this, stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAs = require( './as/get.js' );
var setAs = require( './as/set.js' );

var getCross = require( './cross/get.js' );
var setCross = require( './cross/set.js' );

var getDrop = require( './drop/get.js' );
var setDrop = require( './drop/set.js' );

var getFields = require( './fields/get.js' );
var setFields = require( './fields/set.js' );

var getGroupby = require( './groupby/get.js' );
var setGroupby = require( './groupby/set.js' );

var getKey = require( './key/get.js' );
var setKey = require( './key/set.js' );

var getOps = require( './ops/get.js' );
var setOps = require( './ops/set.js' );

var getProperties = require( './properties/get.js' );


// VARIABLES //

var debug = logger( 'vega:aggregate-transform:main' );


// MAIN //

/**
* Aggregate transform constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {Array<string>} [options.as] - output field names to use for each aggregated field in fields
* @param {boolean} [options.cross=false] - boolean indicating whether to include full cross-product of all groupby values in the aggregate output
* @param {boolean} [options.drop=true] - boolean indicating whether to drop empty (zero count) groups
* @param {Array<Field>} [options.fields=[<Field>]] - data fields for which to compute aggregate functions
* @param {Array<Field>} [options.groupby] - data fields to group by
* @param {Field} [options.key] - optional key field used to optimize groupby key calculation
* @param {Array<string>} [options.ops=['count']] - aggregation operations to apply to the fields
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {AggregateTransform} aggregate transform instance
*
* @example
* var transform = new AggregateTransform();
* // returns <AggregateTransform>
*/
function AggregateTransform( options ) {
	var self;
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof AggregateTransform ) ) {
		if ( arguments.length ) {
			return new AggregateTransform( options );
		}
		return new AggregateTransform();
	}
	self = this;
	EventEmitter.call( this );

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	// Define an internal change event listener:
	this._onChange = onChange;

	// Add change listeners to default event emitters:
	if ( this._fields ) {
		this._addChangeListeners( this._fields );
	}
	if ( this._key && typeof this._key.on === 'function' ) {
		this._addChangeListener( this._key );
	}

	// Validate provided options by attempting to assign option values to corresponding fields...
	if ( arguments.length ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		for ( i = 0; i < properties.length; i++ ) {
			k = properties[ i ];
			if ( !hasProp( options, k ) ) {
				continue;
			}
			v = options[ k ];
			try {
				this[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error. Error: %s', err.message );

				// FIXME: retain thrown error type
				throw new Error( transformErrorMessage( err.message ) );
			}
		}
	}
	return this;

	/**
	* Callback invoked upon a change event.
	*
	* @private
	* @param {Object} event - event object
	*/
	function onChange( event ) {
		debug( 'Received a change event: %s', JSON.stringify( event ) );
		self.emit( 'change', event );
	}
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( AggregateTransform, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof AggregateTransform
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( AggregateTransform, 'name', 'AggregateTransform' );

/**
* Adds an internal listener to a change event on a child instance.
*
* @private
* @name _addChangeListener
* @memberof AggregateTransform.prototype
* @type {Function}
* @param {Object} emitter - event emitter
* @returns {AggregateTransform} aggregate transform instance
*/
setNonEnumerableReadOnly( AggregateTransform.prototype, '_addChangeListener', function addChangeListener( emitter ) {
	if ( emitter && typeof emitter.on === 'function' ) {
		emitter.on( 'change', this._onChange );
	}
	return this;
});

/**
* Adds internal listeners to change events on child instances.
*
* @private
* @name _addChangeListeners
* @memberof AggregateTransform.prototype
* @type {Function}
* @param {ArrayLikeObject<Object>} emitters - list of event emitters
* @returns {AggregateTransform} aggregate transform instance
*/
setNonEnumerableReadOnly( AggregateTransform.prototype, '_addChangeListeners', function addChangeListeners( emitters ) {
	var i;
	for ( i = 0; i < emitters.length; i++ ) {
		this._addChangeListener( emitters[ i ] );
	}
	return this;
});

/**
* Removes an internal listener to a change event on a child instance.
*
* @private
* @name _removeChangeListener
* @memberof AggregateTransform.prototype
* @type {Function}
* @param {Object} emitter - event emitter
* @returns {AggregateTransform} aggregate transform instance
*/
setNonEnumerableReadOnly( AggregateTransform.prototype, '_removeChangeListener', function removeChangeListener( emitter ) {
	if ( emitter && typeof emitter.removeListener === 'function' ) {
		emitter.removeListener( 'change', this._onChange );
	}
	return this;
});

/**
* Removes internal listeners to change events on child instances.
*
* @private
* @name _removeChangeListeners
* @memberof AggregateTransform.prototype
* @type {Function}
* @param {ArrayLikeObject<Object>} emitters - list of event emitters
* @returns {AggregateTransform} aggregate transform instance
*/
setNonEnumerableReadOnly( AggregateTransform.prototype, '_removeChangeListeners', function removeChangeListeners( emitters ) {
	var i;
	for ( i = 0; i < emitters.length; i++ ) {
		this._removeChangeListener( emitters[ i ] );
	}
	return this;
});

/**
* Output field names to use for each aggregated field in fields.
*
* @name as
* @memberof AggregateTransform.prototype
* @type {(Array<string>|void)}
*
* @example
* var transform = new AggregateTransform({
*     'as': [ 'sum_field', 'average_field' ]
* });
*
* var v = transform.as;
* // returns [ 'sum_field', 'average_field' ]
*/
setReadWriteAccessor( AggregateTransform.prototype, 'as', getAs, setAs );

/**
* Boolean indicating whether to include full cross-product of all groupby values in the aggregate output.
*
* @name cross
* @memberof AggregateTransform.prototype
* @type {boolean}
* @default false
*
* @example
* var transform = new AggregateTransform({
*     'cross': true
* });
*
* var v = transform.cross;
* // returns true
*/
setReadWriteAccessor( AggregateTransform.prototype, 'cross', getCross, setCross );

/**
* Boolean indicating whether to drop empty (zero count) groups.
*
* @name drop
* @memberof AggregateTransform.prototype
* @type {boolean}
* @default true
*
* @example
* var transform = new AggregateTransform({
*     'drop': true
* });
*
* var v = transform.drop;
* // returns true
*/
setReadWriteAccessor( AggregateTransform.prototype, 'drop', getDrop, setDrop );

/**
* Data fields for which to compute aggregate functions.
*
* @name fields
* @memberof AggregateTransform.prototype
* @type {Array<Field>}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var fields = [
*     new Field({
*         'field': 'sum',
*         'as': 'sum_field'
*     }),
*     new Field({
*         'field': 'average',
*         'as': 'average_field'
*     })
* ]
* var transform = new AggregateTransform({
*     'fields': fields
* });
*
* var v = transform.fields;
* // returns [ <Field>, <Field> ]
*/
setReadWriteAccessor( AggregateTransform.prototype, 'fields', getFields, setFields );

/**
* Data fields to group by.
*
* @name groupby
* @memberof AggregateTransform.prototype
* @type {(Array<Field>|void)}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var fields = [
*     new Field({
*         'field': 'sum',
*         'as': 'sum_field'
*     })
* ]
* var transform = new AggregateTransform({
*     'groupby': fields
* });
*
* var v = transform.groupby;
* // returns [ <Field> ]
*/
setReadWriteAccessor( AggregateTransform.prototype, 'groupby', getGroupby, setGroupby );

/**
* Optional key field used to optimize groupby key calculation.
*
* @name key
* @memberof AggregateTransform.prototype
* @type {(Field|void)}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var field = new Field({
*     'field': 'sum',
*     'as': 'sum_field'
* })
* var transform = new AggregateTransform({
*     'key': field
* });
*
* var v = transform.key;
* // returns <Field>
*/
setReadWriteAccessor( AggregateTransform.prototype, 'key', getKey, setKey );

/**
* Aggregation operations to apply to the fields.
*
* @name ops
* @memberof AggregateTransform.prototype
* @type {Array<string>}
* @default ['count']
*
* @example
* var transform = new AggregateTransform({
*     'ops': [ 'sum', 'average' ]
* });
*
* var v = transform.ops;
* // returns [ 'sum', 'average' ]
*/
setReadWriteAccessor( AggregateTransform.prototype, 'ops', getOps, setOps );

/**
* Aggregate transform properties.
*
* @name properties
* @memberof AggregateTransform.prototype
* @type {Array<string>}
*
* @example
* var transform = new AggregateTransform();
*
* var v = transform.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( AggregateTransform.prototype, 'properties', getProperties );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof AggregateTransform.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var transform = new AggregateTransform();
*
* var v = transform.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( AggregateTransform.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = AggregateTransform;
